<template>
  <div class="d-workbench" v-loading="loading">
    <aside class="d-conversations">
      <header><span>CLIENT COLLABORATION</span><strong>客户沟通</strong></header>
      <button v-for="item in conversations" :key="item.id" type="button" :class="{ active: item.id === activeId }" @click="openConversation(item.id)">
        <i>{{ (item.customerName || '客').slice(0, 1) }}</i><div><strong>{{ item.projectName }}</strong><small>{{ item.customerName || '客户' }} · {{ item.lastMessage || '暂无消息' }}</small></div><b v-if="item.unreadCount">{{ item.unreadCount }}</b>
      </button>
      <p v-if="!loading && !conversations.length">暂无客户会话</p>
    </aside>
    <section v-if="project" class="d-chat">
      <header class="d-chat-head"><div><h1>{{ project.name }}</h1><p>客户：{{ project.customerName || '—' }} · {{ project.currentStageName }} <b>{{ project.progress }}%</b></p></div><button type="button" @click="router.push(`/projects/${project.id}`)">项目详情 <el-icon><ArrowRight /></el-icon></button></header>
      <div class="d-stage-bar"><button v-for="stage in stages" :key="stage.id" type="button" :class="stage.status.toLowerCase()" @click="operateStage(stage)"><i>{{ stage.sortOrder }}</i><strong>{{ stage.stageName }}</strong><small>{{ stageText(stage) }}</small></button></div>
      <div class="d-stage-note"><el-icon><InfoFilled /></el-icon>{{ stageNote }}</div>
      <div ref="messageBox" class="d-message-list">
        <template v-for="message in messages" :key="message.id"><p v-if="message.senderRole === 'SYSTEM'" class="d-system">{{ message.content }}</p><article v-else :class="{ mine: message.senderId === auth.user?.id }"><i>{{ message.senderName.slice(0, 1) }}</i><div><small>{{ message.senderName }} · {{ formatTime(message.createdAt) }}</small><section><p v-if="message.content">{{ message.content }}</p><a v-for="file in message.files" :key="file.id" href="#" @click.prevent="downloadAttachment(file.id, file.originalName)"><el-icon><Paperclip /></el-icon>{{ file.originalName }}</a></section></div></article></template>
      </div>
      <footer class="d-composer"><div class="d-tools"><button type="button" title="添加表情" @click="emojiVisible = !emojiVisible"><el-icon><Sunny /></el-icon></button><button type="button" title="上传图片或文件" @click="input?.click()"><el-icon><Paperclip /></el-icon></button><input ref="input" type="file" hidden accept="image/*,.pdf,.doc,.docx,.xls,.xlsx,.zip" @change="chooseFile" /><span v-if="fileToSend">{{ fileToSend.name }} <button type="button" @click="fileToSend = null">移除</button></span></div><div v-if="emojiVisible" class="d-emojis"><button v-for="emoji in emojis" :key="emoji" type="button" @click="text += emoji">{{ emoji }}</button></div><el-input v-model="text" type="textarea" :autosize="{ minRows: 3, maxRows: 5 }" placeholder="输入消息，按 Ctrl + Enter 发送" @keydown.ctrl.enter.prevent="send" /><div class="d-send"><small>支持文字、图片、文件与表情</small><el-button type="primary" :loading="sending" @click="send">发送</el-button></div></footer>
    </section>
    <section v-else-if="!loading" class="d-chat-empty">选择一个客户会话开始沟通。</section>
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowRight, InfoFilled, Paperclip, Sunny } from '@element-plus/icons-vue'
import { confirmStageAction, createStageAction, downloadFile, getProject, listConversations, listMessages, listProjectActions, listProjectStages, markConversationRead, rejectStageAction, sendMessage, uploadFile } from '@/api'
import type { ConversationVO, FileAssetVO, MessageVO, ProjectStageVO, ProjectVO, StageActionVO } from '@/models'
import { useAuthStore } from '@/stores/auth'

const router = useRouter(); const auth = useAuthStore()
const loading = ref(false); const sending = ref(false); const conversations = ref<ConversationVO[]>([]); const activeId = ref<number | null>(null); const project = ref<ProjectVO | null>(null); const stages = ref<ProjectStageVO[]>([]); const actions = ref<StageActionVO[]>([]); const messages = ref<MessageVO[]>([]); const text = ref(''); const fileToSend = ref<File | null>(null); const input = ref<HTMLInputElement | null>(null); const messageBox = ref<HTMLElement | null>(null); const emojiVisible = ref(false); const emojis = ['😀', '👍', '🎨', '✨', '📎', '✅']
const activeConversation = computed(() => conversations.value.find((item) => item.id === activeId.value) || null)
const stageNote = computed(() => { const pending = stages.value.find((item) => item.status === 'PENDING_CONFIRM'); return pending ? `阶段「${pending.stageName}」正在等待对方确认。` : '点击阶段可向客户发起确认，所有操作都会留下系统记录。' })
const latestAction = (code: string) => actions.value.filter((item) => item.stageCode === code).sort((a, b) => b.id - a.id)[0]
const stageText = (stage: ProjectStageVO) => ({ REACHED: '已达成', PENDING_CONFIRM: '等待确认', REJECTED: '已驳回', TODO: '待发起' }[stage.status] || stage.status)
const stageTemplate = (stage: ProjectStageVO) => stage.stageCode === 'REQUIREMENT_GUIDE' ? '已发送需求引导模板，请客户补充品牌背景、目标用户、传播目标、风格参考与交付时间。' : `发起「${stage.stageName}」确认，请客户核对后确认或提出修改意见。`

async function refreshMessages() { if (!activeConversation.value) return; const page = await listMessages(activeConversation.value.id, { size: 100 }); messages.value = page.records; const last = messages.value.at(-1); if (last) await markConversationRead(activeConversation.value.id, { lastReadMessageId: last.id }); await nextTick(); messageBox.value?.scrollTo({ top: messageBox.value.scrollHeight }) }
async function openConversation(id: number) { activeId.value = id; const item = conversations.value.find((value) => value.id === id); if (!item) return; loading.value = true; try { const data = await Promise.all([getProject(item.projectId), listProjectStages(item.projectId), listProjectActions(item.projectId)]); project.value = data[0]; stages.value = data[1]; actions.value = data[2]; await refreshMessages() } catch (error) { ElMessage.error(error instanceof Error ? error.message : '会话加载失败') } finally { loading.value = false } }
async function operateStage(stage: ProjectStageVO) { if (!project.value || stage.status === 'REACHED') return; const action = latestAction(stage.stageCode); try { if (stage.status === 'PENDING_CONFIRM' && action) { if (action.confirmUserId !== auth.user?.id) { ElMessage.info('已发起确认，正在等待客户处理。'); return } try { await ElMessageBox.confirm(`确认达成「${stage.stageName}」吗？`, '处理客户确认', { confirmButtonText: '确认达成', cancelButtonText: '驳回', distinguishCancelAndClose: true, type: 'info' }); await confirmStageAction(action.id, { responseNote: '设计师已确认。' }) } catch (decision) { if (decision === 'cancel') await rejectStageAction(action.id, { responseNote: '请补充或修改后重新提交。' }); else return } } else { const note = stageTemplate(stage); await ElMessageBox.confirm(`将向客户发起「${stage.stageName}」确认。`, '发起阶段确认', { confirmButtonText: '发起确认', cancelButtonText: '取消', type: 'info' }); if (stage.stageCode === 'REQUIREMENT_GUIDE' && activeConversation.value) await sendMessage(activeConversation.value.id, { messageType: 'TEXT', content: note, fileIds: [] }); await createStageAction(project.value.id, stage.stageCode, { requestNote: note }); ElMessage.success('已发起确认，等待客户处理。') } } catch (error) { if (error === 'cancel' || error === 'close') return; ElMessage.error(error instanceof Error ? error.message : '操作失败') } await openConversation(activeId.value || 0) }
function chooseFile(event: Event) { fileToSend.value = (event.target as HTMLInputElement).files?.[0] || null; if (input.value) input.value.value = '' }
async function send() { if (!activeConversation.value || (!text.value.trim() && !fileToSend.value)) return; sending.value = true; try { let asset: FileAssetVO | null = null; if (fileToSend.value) asset = await uploadFile(fileToSend.value); const message = await sendMessage(activeConversation.value.id, { messageType: asset ? (asset.mimeType?.startsWith('image/') ? 'IMAGE' : 'FILE') : 'TEXT', content: text.value.trim() || null, fileIds: asset ? [asset.id] : [], clientMessageId: `designer-${Date.now()}` }); messages.value.push(message); text.value = ''; fileToSend.value = null; await nextTick(); messageBox.value?.scrollTo({ top: messageBox.value.scrollHeight, behavior: 'smooth' }) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '发送失败') } finally { sending.value = false } }
async function downloadAttachment(id: number, name: string) { try { const blob = await downloadFile(id); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '下载失败') } }
const formatTime = (value?: string | null) => value ? value.replace('T', ' ').slice(5, 16) : ''
onMounted(async () => { loading.value = true; try { conversations.value = await listConversations(); if (conversations.value[0]) await openConversation(conversations.value[0].id) } catch (error) { ElMessage.error(error instanceof Error ? error.message : '会话列表加载失败') } finally { loading.value = false } })
</script>

<style>
.d-workbench { min-height: calc(100vh - 111px); display: grid; grid-template-columns: 285px minmax(0, 1fr); overflow: hidden; border: 1px solid #d9e5e9; background: #fff; }.d-conversations { border-right: 1px solid #e4edf0; background: #fbfcfc; }.d-conversations header { padding: 22px 18px 16px; display: grid; gap: 4px; }.d-conversations header span { color: #087b76; font-size: 10px; font-weight: 800; letter-spacing: 1px; }.d-conversations header strong { font-size: 18px; }.d-conversations > button { width: 100%; min-height: 74px; padding: 12px 14px; border: 0; border-top: 1px solid #edf2f3; display: flex; align-items: center; gap: 9px; position: relative; background: transparent; text-align: left; cursor: pointer; }.d-conversations > button.active { background: #eaf7f5; }.d-conversations > button > i, .d-message-list article > i { width: 34px; height: 34px; flex: none; border-radius: 8px; display: grid; place-items: center; background: #d6f0eb; color: #087b76; font-style: normal; font-size: 13px; font-weight: 800; }.d-conversations button > div { min-width: 0; display: grid; gap: 5px; }.d-conversations button strong { color: #33465a; font-size: 13px; }.d-conversations button small { overflow: hidden; color: #7d8d9e; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }.d-conversations button b { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; position: absolute; right: 12px; top: 12px; background: #087b76; color: #fff; font-size: 10px; }.d-conversations > p { padding: 45px 10px; color: #94a2af; text-align: center; font-size: 12px; }.d-chat { min-width: 0; display: grid; grid-template-rows: auto auto auto minmax(300px, 1fr) auto; }.d-chat-head { padding: 18px 24px; border-bottom: 1px solid #e7edef; display: flex; align-items: center; justify-content: space-between; }.d-chat-head h1 { margin: 0; font-size: 18px; }.d-chat-head p { margin: 6px 0 0; color: #7a8a9c; font-size: 12px; }.d-chat-head p b { margin-left: 4px; color: #087b76; }.d-chat-head button { padding: 0; border: 0; display: inline-flex; align-items: center; gap: 4px; background: transparent; color: #087b76; cursor: pointer; font-size: 13px; }.d-stage-bar { padding: 12px 17px; display: grid; grid-template-columns: repeat(7, minmax(100px, 1fr)); gap: 7px; overflow-x: auto; border-bottom: 1px solid #e7edef; }.d-stage-bar button { min-height: 62px; padding: 8px; border: 1px solid #dce6e8; display: grid; grid-template-columns: 20px 1fr; column-gap: 4px; background: #fff; color: #516174; cursor: pointer; text-align: left; }.d-stage-bar button > i { width: 18px; height: 18px; grid-row: span 2; border-radius: 50%; display: grid; place-items: center; background: #eaf0f2; color: #728598; font-size: 10px; font-style: normal; font-weight: 700; }.d-stage-bar strong { font-size: 12px; line-height: 1.25; }.d-stage-bar small { color: #8a9aa9; font-size: 10px; }.d-stage-bar button.reached { border-color: #bee0d2; background: #f3fbf7; }.d-stage-bar button.reached > i { background: #d6efe2; color: #26764c; }.d-stage-bar button.pending_confirm { border-color: #efd89f; background: #fff9ed; }.d-stage-bar button.pending_confirm > i { background: #ffe4a8; color: #936300; }.d-stage-bar button.rejected { border-color: #edc4c4; background: #fff7f7; }.d-stage-note { padding: 9px 24px; display: flex; align-items: center; gap: 7px; background: #f0f8f7; color: #5b7280; font-size: 12px; }.d-stage-note .el-icon { color: #087b76; }.d-message-list { min-height: 0; padding: 23px 25px; overflow: auto; display: grid; align-content: start; gap: 14px; }.d-system { justify-self: center; margin: 0; padding: 5px 10px; background: #f0f3f4; color: #7e8d99; font-size: 11px; }.d-message-list article { max-width: min(75%, 540px); display: flex; align-items: flex-start; gap: 8px; }.d-message-list article.mine { justify-self: end; flex-direction: row-reverse; }.d-message-list article > i { width: 30px; height: 30px; border-radius: 7px; font-size: 12px; }.d-message-list article > div { min-width: 0; }.d-message-list article small { display: block; margin-bottom: 5px; color: #738397; font-size: 11px; }.d-message-list article.mine small { text-align: right; }.d-message-list section { padding: 9px 11px; border-radius: 3px 11px 11px; background: #f1f5f5; color: #354a56; font-size: 13px; line-height: 1.65; }.d-message-list article.mine section { border-radius: 11px 3px 11px 11px; background: #d8f2ed; color: #185f5a; }.d-message-list section p { margin: 0; white-space: pre-wrap; }.d-message-list section a { margin-top: 5px; padding: 6px 7px; display: flex; align-items: center; gap: 4px; background: rgba(255,255,255,.55); color: inherit; font-size: 12px; }.d-composer { padding: 10px 18px 13px; border-top: 1px solid #e7edef; }.d-tools { min-height: 26px; display: flex; align-items: center; gap: 3px; }.d-tools > button { width: 26px; height: 26px; border: 0; display: grid; place-items: center; background: transparent; color: #708396; cursor: pointer; }.d-tools .el-icon { font-size: 17px; }.d-tools > span { margin-left: 5px; padding: 3px 6px; background: #edf6f4; color: #47716c; font-size: 11px; }.d-tools span button { margin-left: 4px; padding: 0; border: 0; background: transparent; color: #bf5c5c; cursor: pointer; font-size: 11px; }.d-emojis { padding: 6px 0; display: flex; gap: 4px; }.d-emojis button { padding: 2px; border: 0; background: transparent; cursor: pointer; font-size: 17px; }.d-composer .el-textarea__inner { padding: 8px 0; box-shadow: none; resize: none; font-size: 13px; }.d-send { display: flex; align-items: center; justify-content: space-between; }.d-send small { color: #98a7b2; font-size: 11px; }.d-composer .el-button--primary { --el-button-bg-color: #087b76; --el-button-border-color: #087b76; --el-button-hover-bg-color: #0b938c; --el-button-hover-border-color: #0b938c; }.d-chat-empty { display: grid; place-items: center; border: 1px solid #d9e5e9; color: #8a9aa8; background: #fff; }
@media (max-width: 900px) { .d-workbench { grid-template-columns: 1fr; }.d-conversations { max-height: 185px; overflow: auto; border-right: 0; border-bottom: 1px solid #e4edf0; }.d-conversations header { padding: 12px 15px; }.d-conversations > button { min-height: 58px; }.d-stage-bar { grid-template-columns: repeat(7, 115px); }.d-message-list { padding: 17px; }.d-message-list article { max-width: 88%; }.d-chat-head, .d-stage-note { padding-left: 17px; padding-right: 17px; } }
</style>
